{
  "userQuery": "搞个快递卡片，背景放图字叠上去，写一句还有几个在路上，点一下导航去取件，从日历读日程，已签收的标出来",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "StartNavigate",
        "params": {
          "dstLocation": {
            "latitude": "22.3193",
            "longitude": "114.1694"
          },
          "trafficpe": "Walk"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "title": {
              "type": "string",
