              "sampleValue": "小区东门驿站"
            },
            "dtStart": {
              "type": "string",
              "description": "取件提醒时间",
              "sampleValue": "18:30"
            }
          },
          {
            "title": {
              "type": "string",
              "description": "已签收快递名称",
              "sampleValue": "耳机保护套"
            },
            "description": {
              "type": "string",
              "description": "签收状态",
              "sampleValue": "已签收"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "彩色快递箱子图标，适合用作物流卡片的背景视觉锚点或包裹识别素材。"
    }
  ]
}

